#!/usr/bin/env bash
# Writes the Homebrew formula for one release to stdout, in the layout the
# oxGrad/homebrew-tap formulae use (one file at the tap root, per-platform
# urls). Usage: homebrew-formula.sh <tag> <owner/repo> <dir with tern-<target>.tar.gz>
set -euo pipefail

tag="$1"
repo="$2"
dir="$3"
version="${tag#v}"
base="https://github.com/${repo}/releases/download/${tag}"

sha() { sha256sum "${dir}/tern-$1.tar.gz" | cut -d' ' -f1; }

cat <<EOF
# typed: false
# frozen_string_literal: true

# Generated by tern's .github/workflows/publish.yml. DO NOT EDIT.
class Tern < Formula
  desc "Team GitHub activity dashboard: PRs, reviews and commits per member"
  homepage "https://github.com/${repo}"
  version "${version}"
  license "Apache-2.0"

  on_macos do
    if Hardware::CPU.arm?
      url "${base}/tern-aarch64-apple-darwin.tar.gz"
      sha256 "$(sha aarch64-apple-darwin)"
    end
  end

  on_linux do
    if Hardware::CPU.intel? && Hardware::CPU.is_64_bit?
      url "${base}/tern-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "$(sha x86_64-unknown-linux-gnu)"
    end
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "${base}/tern-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "$(sha aarch64-unknown-linux-gnu)"
    end
  end

  def install
    bin.install "tern"
  end

  test do
    system "#{bin}/tern", "--version"
  end
end
EOF
